Definition dfinal (Σ : rtsA) (PMc : Model -> Prop) (F : bvmap 5 word) (gp s7 s8 s9 s10 s11 w0 w1 w2 w3 w4 w5 s6 : word) (lo usp : Z) (m : mem) :
  config -> Prop :=
  fun cf => exists Σ' : rtsA,
    ASTA RTA Σ' PMc (dpost Σ' F gp s7 s8 s9 s10 s11 w0 w1 w2 w3 w4 w5 s6 lo usp (live Σ) (frames Σ) m) cf
    /\ live Σ' = live Σ /\ frames Σ' = frames Σ /\ lay Σ' = lay Σ /\ credit Σ' = credit Σ.

Theorem drain_xfer : forall (Σ : rtsA) (PMc : Model -> Prop) (ra0 gp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s7 s8 s9 s10 s11
         t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem) (lo usp : Z) (w0 w1 w2 w3 w4 w5 s6 : word),
  fdfs_only PMc -> mat_stable PMc ->
  ARTc Σ m -> rt_wfx Σ -> rt_count Σ -> 0x100000 < RT_state.qbytes (ql Σ) ->
  qput_frame m (usp + -2208) (Z_to_bv 64 (l_T (lay Σ) + 208)) (Z_to_bv 64 (usp + -2128)) (Z_to_bv 64 0xcb618) w0 w1 w2 w3 w4 w5 s6 ->
  stk asegs m lo (usp + -2208) -> l_ACEIL (lay Σ) <= lo -> lo + 0x4000 <= usp + -2208 -> usp <= 2 ^ 47 ->
  mem_inv asegs m ->
  R_quar_defs.qbytes (qg Σ ++ ql Σ) <= 0x10000000 ->
  cps asegs (ASTA RTA Σ PMc (eq (xms0 Σ ra0 gp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m usp)))
    (dfinal Σ PMc F gp s7 s8 s9 s10 s11 w0 w1 w2 w3 w4 w5 s6 lo usp m).
Proof.
